WITH RankedAnswersScore AS (
    SELECT 
        p.Id AS AnswerId,
        p.ParentId AS QuestionId,
        p.CreationDate,
        u.Id AS OwnerUser,
        u.DisplayName,
        p.Score,
        RANK() OVER (PARTITION BY p.ParentId ORDER BY p.Score DESC, p.CreationDate ASC) AS AnswerRank
    FROM Posts p
    LEFT JOIN Users u ON p.OwnerUserId = u.Id
    WHERE p.PostTypeId = 2
),
